// Builders for golden vectors: manifests, contexts and hand-written event streams. Everything here is
// deterministic; expected results live in expected.ts (generated by scripts/write-expected.ts and
// reviewed, then append-only: changing one needs a scoring-major bump).
import type { GameContent } from "../schema/content.ts";
import type { GameEvent, GameEventType, PayloadOf } from "../schema/events.ts";
import type { GameId, GameMode } from "../schema/ids.ts";
import { type GameManifest, MANIFEST_LABEL, type SessionContext } from "../schema/manifest.ts";
import type { ReplayPackage, SessionResult } from "../schema/result.ts";
import { GAME_CONFIG } from "../scoring/config.ts";
import { encodeReplay } from "../sdk/replay-codec.ts";

export interface GoldenVector {
  name: string;
  description: string;
  /** strong | medium | weak | critical | voided | edge … */
  tags: readonly string[];
  manifest: GameManifest;
  ctx: SessionContext;
  replayPackage: ReplayPackage;
  content: GameContent;
  expectedResult: SessionResult;
}

export type VectorInput = Omit<GoldenVector, "expectedResult">;

/** A valid UUID (version 4 layout) from a small integer, so vector IDs stay readable. */
export function fixtureSid(n: number): string {
  return `00000000-0000-4000-8000-${n.toString(16).padStart(12, "0")}`;
}

