/** A valid reference manifest for a game that has a scorer. */
export function manifestFor(
  gameId: GameId,
  version = "1.0.0",
  scoringVersion = "1.0",
): GameManifest {
  const b = BITS[gameId];
  if (b === undefined) throw new Error(`no fixture manifest for ${gameId}`);
  return {
    gameId,
    code: CODE[gameId],
    version,
    scoringVersion,
    telemetryVersion: 1,
    engine: b.engine,
    modules: b.modules,
    skills: b.skills,
    ruleIds: b.ruleIds,
    findingIds: b.findingIds,
    drillIds: b.drillIds,
    modes: b.modes,
    debriefMode: "ai_or_template",
    minUserBand: "u18",
    u18Behaviour: "full",
    offline: gameId === "ll_sim",
    liteMode: b.liteMode,
    a11yModes: ["no_audio", "colour_safe", "tap_only"],
    assets: [],
    budgets: { chunkKbGzip: 120, ...GAME_CONFIG.budgets[gameId] },
    label: { en: MANIFEST_LABEL.en, hi: MANIFEST_LABEL.hi },
    contentGate: {
      medicalReview: false,
      reviewedBy: null,
      reviewedOn: null,
      draftLabelUntilReviewed: false,
    },
  };
}

export interface CtxSpec {
  n: number;
  gameId: GameId;
  mode: GameMode;
  seed: number;
  items: { ref: string; contentVersion: string }[];
  tenant?: string;
  difficulty?: number;
  seedOrigin?: SessionContext["seedOrigin"];
}

export function ctxFor(s: CtxSpec): SessionContext {
  return {
    sid: fixtureSid(s.n),
    gameId: s.gameId,
    mode: s.mode,
    userBand: "adult",
    locale: "en",
    a11y: { modes: [], textScale: 1, haptics: false },
    difficulty: s.difficulty ?? 3,
    seed: s.seed,
    seedOrigin: s.seedOrigin ?? "server",
    items: s.items,
    deviceClass: "mid",
    offline: false,
    serverStartIso: "2026-10-24T09:00:00Z",
    tenant: s.tenant ?? "JK",
    rulePackVersion: "2026.10.23",
  };
}

/** Hand-written event stream with automatic `seq`. */
export class StreamBuilder {
  readonly events: GameEvent[] = [];
  readonly #sid: string;
  constructor(sid: string) {
    this.#sid = sid;
  }
  push<T extends GameEventType>(
    type: T,
    p: PayloadOf<T>,
    at: { t: number; mt?: number; item?: number },
  ): this {
    const e: Record<string, unknown> = {
      sid: this.#sid,
      seq: this.events.length,
      t: at.t,
      type,
      p,
    };
    if (at.mt !== undefined) e["mt"] = at.mt;
    if (at.item !== undefined) e["item"] = at.item;
    this.events.push(e as GameEvent);
    return this;
  }
  /** Events sorted by t (stable), with seq reassigned. Builders may push out of order. */
  build(): GameEvent[] {
    return this.events
      .map((e, i) => ({ e, i }))
      .sort((a, b) => a.e.t - b.e.t || a.i - b.i)
      .map(({ e }, seq) => ({ ...e, seq }));
  }
}

export function vector(
  v: Omit<VectorInput, "replayPackage" | "manifest"> & {
    events: readonly GameEvent[];
    manifest?: GameManifest;
  },
): VectorInput {
  return {
    name: v.name,
    description: v.description,
    tags: v.tags,
    manifest: v.manifest ?? manifestFor(v.ctx.gameId),
    ctx: v.ctx,
    replayPackage: encodeReplay(v.events, v.ctx.seed),
    content: v.content,
  };
}
